package service
import("testing";"time";"ballast-watch/internal/model";"ballast-watch/internal/store")
func TestBug25_ComplianceWindowLooksBack(t *testing.T){svc:=ballastTestServices(t);v:=mustVessel(t,svc);tank:=mustTank(t,svc,v);p:=mustPointBallast(t,svc,tank);_,err:=svc.Rules.Create(ballastCtx(),&model.ComplianceRuleInput{BallastTankID:tank.ID,Code:"SAL",ParamType:model.ParamHumidity,Op:model.OpGt,Threshold:80,DurationSec:5,Level:model.ComplianceAlertAlarm,Enabled:true});if err!=nil{t.Fatal(err)};now:=time.Now();_,err=svc.Store.Exec("INSERT INTO water_readings (sampling_sampling_point_id,sensor_id,param_type,value,measured_at,created_at) VALUES (?,?,?,?,?,?)",p.ID,1,model.ParamHumidity,99,now.Add(-time.Second),now);if err!=nil{t.Fatal(err)};svc.Engine.WithWaterWaterReadingStore(store.NewWaterWaterReadingStore(svc.Store));if err:=svc.Engine.Evaluate(ballastCtx(),[]*model.WaterReading{{SamplingPointID:p.ID,ParamType:model.ParamHumidity,Value:99,MeasuredAt:now}});err!=nil{t.Fatal(err)};alerts,_:=svc.ComplianceAlerts.List(ballastCtx(),model.ComplianceComplianceAlertInput{BallastTankID:tank.ID});if len(alerts)!=1{t.Fatalf("expected alert, got %d",len(alerts))}}
